{"ASK_GROUP","role=law_corrections|tmp=seasoned|st=friendly,neutral",{"Other guards, ten of us, we run the old jail as a shelter"}},
{"ASK_GROUP","role=law_corrections|tmp=seasoned|st=careful",{"The jail crew - that's all"}},
{"ASK_GROUP","role=swat_lead,swat_operator|tmp=veteran|st=friendly,neutral",{"Team of six - county tactical"}},
