{"ASK_GROUP","role=soldier,soldier_green|tmp=seasoned,fresh|st=friendly,neutral",{"I'm with the unit, what's left of it"}},
{"ASK_GROUP","role=soldier,soldier_green|tmp=seasoned,fresh|st=careful",{"Can't discuss unit composition"}},
{"ASK_GROUP","role=soldier_nco|tmp=veteran|st=friendly,neutral|world=road",{"I'm attached to a squad, we hold this road"}},
