{"ASK_GROUP","role=elite_operator,elite_delta,mercenary|tmp=veteran|st=friendly,neutral",{"A small team"}},
{"ASK_GROUP","role=elite_operator,elite_delta,mercenary|tmp=veteran|st=careful",{"I'm not alone - that's enough"}},
{"ASK_GROUP","role=outlaw|tmp=seasoned|st=friendly,neutral",{"A few drifters, we share a fire when we can"}},
{"ASK_GROUP","role=outlaw|tmp=seasoned|st=careful",{"Folks you don't want to meet"}},
{"ASK_GROUP","role=raider,raider_boss|tmp=predator|st=friendly,neutral",{"The crew, twelve of us, and it's growing","My people, bunch of guys who like taking"}},
{"ASK_GROUP","role=raider,raider_boss|tmp=predator|st=careful",{"You'll meet them soon enough"}},
{"ASK_GROUP","role=gang_member,gang_boss|tmp=predator|st=friendly,neutral",{"My set - fifteen strong - ask anybody on the block"}},
